package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_ValidBasic() {
        byte[] buffer = "000123 ".getBytes();
        // length 7, offset 0. Trailing space is handled.
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, 7));
    }

    @Test
    public void testParseOctal_ValidWithNUL() {
        byte[] buffer = "000755\0\0".getBytes();
        // length 7, offset 0. Trailing NULs are handled.
        assertEquals(493L, TarUtils.parseOctal(buffer, 0, 7));
    }

    @Test
    public void testParseOctal_ValidWithLeadingSpaces() {
        byte[] buffer = "   012 ".getBytes();
        assertEquals(10L, TarUtils.parseOctal(buffer, 0, 7));
    }

    @Test
    public void testParseOctal_AllNUL() {
        byte[] buffer = new byte[]{0, 0, 0, 0};
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 4));
    }

    @Test
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "1".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 1);
            fail("Expected IllegalArgumentException for length < 2");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("must be at least 2"));
        }
    }

    @Test
    public void testParseOctal_InvalidTrailingCharacter() {
        byte[] buffer = "01234X".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 6);
            fail("Expected IllegalArgumentException for invalid trailer");
        } catch (IllegalArgumentException e) {
            // Message contains exceptionMessage details
        }
    }

    @Test
    public void testParseOctal_InvalidOctalDigit() {
        byte[] buffer = "0128 ".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 5);
            fail("Expected IllegalArgumentException for digit '8'");
        } catch (IllegalArgumentException e) {
            // Message contains exceptionMessage details
        }
    }

    @Test
    public void testParseOctal_InvalidOctalDigitLow() {
        byte[] buffer = "012/ ".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 5);
            fail("Expected IllegalArgumentException for character '/'");
        } catch (IllegalArgumentException e) {
            // Message contains exceptionMessage details
        }
    }

    @Test
    public void testParseOctal_OffsetUsage() {
        byte[] buffer = "junk 012 ".getBytes();
        // offset 5, length 5 -> "012 "
        assertEquals(10L, TarUtils.parseOctal(buffer, 5, 5));
    }

    @Test
    public void testParseOctal_DoubleTrailingNULOrSpace() {
        // Testing the logic: trailer = buffer[end-1]; if (trailer == 0 || trailer == ' ') end--;
        // The code has two consecutive checks for trailers to handle cases like "\0\0" or "\0 "
        byte[] buffer = "012 \0 ".getBytes(); 
        // start=0, end=6. 
        // trailer = buffer[5] (' ') -> end=5
        // trailer = buffer[4] ('\0') -> end=4
        // loop from 0 to 4 -> "012 "
        assertEquals(10L, TarUtils.parseOctal(buffer, 0, 6));
    }

    @Test
    public void testParseOctal_ComplexTrailing() {
        byte[] buffer = "012\0 ".getBytes();
        // end=5. buffer[4] is ' '. end becomes 4.
        // buffer[3] is '\0'. end becomes 3.
        // loop 0 to 3 -> "012"
        assertEquals(10L, TarUtils.parseOctal(buffer, 0, 5));
    }
}
